import Foundation
import Testing
@testable import PixlLibrary

/// The golden vectors of Song Tap's pure core. The files in `Fixtures/songtap` are GENERATED by the Android repo's
/// `./gradlew :songtap:generateGolden` and copied here unchanged; `README.md` beside them says how each `fn` is
/// replayed. The Swift core must reproduce every `out` from its `in`, byte for byte: each test rebuilds the canonical
/// `"out":{...}` text with `BrainJson.Writer` (the same canonical JSON) and compares it with the bytes of the line.
/// Never edit a golden file by hand; when the Kotlin changes, copy the folder again.
@Suite("Song Tap golden vectors (songTapMatchesAndroid)")
struct SongTapGoldenTests {
    typealias Value = BrainJson.Value

    // MARK: Reading

    static func fixtureData(_ name: String) throws -> Data {
        let base = (name as NSString).deletingPathExtension
        let ext = (name as NSString).pathExtension
        let url = try #require(Bundle.module.url(forResource: base, withExtension: ext.isEmpty ? nil : ext,
                                                 subdirectory: "Fixtures/songtap"))
        return try Data(contentsOf: url)
    }

    static func lines(_ name: String) throws -> [String] {
        let text = String(decoding: try fixtureData(name), as: UTF8.self)
        return text.split(separator: "\n", omittingEmptySubsequences: true).map(String.init)
    }

    struct Case {
        let fn: String
        let input: Value
        let line: String
        let number: Int

        /// True when the canonical `"out"` object that `build` writes is exactly the one in the file.
        func matches(_ build: (inout BrainJson.Writer) -> Void) -> Bool {
            var w = BrainJson.Writer()
            w.beginObject("out")
            build(&w)
            w.endObject()
            return line.hasSuffix("," + w.text + "}")
        }
    }

    static func cases(_ name: String) throws -> [Case] {
        var out: [Case] = []
        for (i, line) in try lines(name).enumerated() {
            let v = try BrainJson.parse(line)
            out.append(Case(fn: v["fn"]?.stringValue ?? "", input: try #require(v["in"]), line: line, number: i + 1))
        }
        return out
    }

    struct Report {
        let file: String
        var checked = 0
        var counts: [String: Int] = [:]
        var failures: [String] = []

        mutating func record(_ c: Case, _ ok: Bool) {
            checked += 1
            counts[c.fn, default: 0] += 1
            if !ok && failures.count < 5 { failures.append("\(file):\(c.number) \(c.fn): \(String(c.line.prefix(240)))") }
        }

        func verify(atLeast: Int) {
            #expect(failures.isEmpty, "\(failures.joined(separator: "\n"))")
            #expect(checked >= atLeast, "\(file): only \(checked) cases were replayed")
        }
    }

    // MARK: Small readers and writers

    static func long(_ v: Value, _ k: String) -> Int64 { v[k]?.longValue ?? 0 }
    static func int(_ v: Value, _ k: String) -> Int { Int(v[k]?.bareLong ?? 0) }
    static func bool(_ v: Value, _ k: String) -> Bool { v[k]?.boolValue ?? false }
    static func string(_ v: Value, _ k: String) -> String { v[k]?.stringValue ?? "" }
    static func optionalString(_ v: Value, _ k: String) -> String? { v[k]?.stringValue }
    static func strings(_ v: Value, _ k: String) -> [String] { (v[k]?.arrayValue ?? []).map { $0.stringValue ?? "" } }

    static func bytes(_ hex: String) -> [UInt8] {
        let digits = Array(hex.utf8)
        var out: [UInt8] = []
        var i = 0
        func nibble(_ c: UInt8) -> UInt8 { c >= 0x61 ? c - 0x61 + 10 : c - 0x30 }
        while i + 1 < digits.count {
            out.append(nibble(digits[i]) << 4 | nibble(digits[i + 1]))
            i += 2
        }
        return out
    }

    static func hex(_ bytes: [UInt8]) -> String {
        let digits = Array("0123456789abcdef".utf8)
        var out: [UInt8] = []
        for b in bytes { out.append(digits[Int(b >> 4)]); out.append(digits[Int(b & 15)]) }
        return String(decoding: out, as: UTF8.self)
    }

    static func writeOptional(_ w: inout BrainJson.Writer, _ name: String, _ value: String?) {
        if let value { w.string(name, value) } else { w.nullValue(name) }
    }

    static func writeHex(_ w: inout BrainJson.Writer, _ name: String, _ value: [UInt8]?) {
        if let value { w.string(name, hex(value)) } else { w.nullValue(name) }
    }

    static func writeFields(_ w: inout BrainJson.Writer, _ p: SongTapPayload) {
        w.int("v", p.v); w.long("ts", p.ts)
        writeOptional(&w, "yt", p.ytVideoId); writeOptional(&w, "sp", p.spotifyId); writeOptional(&w, "isrc", p.isrc)
        w.string("t", p.title); w.string("a", p.artist); w.int("d", p.durationMs)
        writeOptional(&w, "art", p.artUrl)
    }

    static func payload(_ v: Value) -> SongTapPayload {
        SongTapPayload(v: int(v, "v"), ts: long(v, "ts"), ytVideoId: optionalString(v, "yt"), spotifyId: optionalString(v, "sp"),
                       isrc: optionalString(v, "isrc"), title: string(v, "t"), artist: string(v, "a"), durationMs: int(v, "d"),
                       artUrl: optionalString(v, "art"))
    }

    // MARK: payload.jsonl

    @Test func payloadEncodeDecodeMakeAndSanitize() throws {
        var report = Report(file: "payload.jsonl")
        for c in try Self.cases("payload.jsonl") {
            switch c.fn {
            case "encode":
                let out = SongTapPayloads.encode(Self.payload(c.input))
                report.record(c, c.matches { Self.writeHex(&$0, "hex", out) })
            case "decode":
                let result = SongTapPayloads.decode(Self.bytes(Self.string(c.input, "hex")))
                report.record(c, c.matches {
                    switch result {
                    case .ok(let p): $0.bool("ok", true); Self.writeFields(&$0, p)
                    case .rejected(let reason): $0.bool("ok", false); $0.string("reason", reason.code)
                    }
                })
            case "make":
                let made = SongTapPayloads.make(nowMs: Self.long(c.input, "now"), ytVideoId: Self.optionalString(c.input, "yt"),
                                                spotifyId: Self.optionalString(c.input, "sp"), isrc: Self.optionalString(c.input, "isrc"),
                                                title: Self.string(c.input, "t"), artist: Self.string(c.input, "a"),
                                                durationMs: Self.long(c.input, "d"), artUrl: Self.optionalString(c.input, "art"))
                report.record(c, c.matches {
                    if let made {
                        $0.bool("ok", true); Self.writeFields(&$0, made); Self.writeHex(&$0, "hex", SongTapPayloads.encode(made))
                    } else {
                        $0.bool("ok", false)
                    }
                })
            case "sanitize":
                let text = SongTapText.sanitize(Self.string(c.input, "text"), maxBytes: Self.int(c.input, "max"))
                report.record(c, c.matches { $0.string("text", text) })
            default:
                report.record(c, false)
            }
        }
        #expect(report.counts["encode"] ?? 0 >= 50)
        #expect(report.counts["decode"] ?? 0 >= 800)
        #expect(report.counts["make"] ?? 0 >= 10)
        #expect(report.counts["sanitize"] ?? 0 >= 50)
        report.verify(atLeast: 950)
    }

