    @Test func signingBytesFramesAndSenderKeys() throws {
        var report = Report(file: "signing.jsonl")
        for c in try Self.cases("signing.jsonl") {
            switch c.fn {
            case "signingBytes":
                let out = SongTapSigning.signingBytes(payload: Self.bytes(Self.string(c.input, "payload")),
                                                     challenge: Self.bytes(Self.string(c.input, "challenge")),
                                                     timestampMs: Self.long(c.input, "ts"))
                report.record(c, c.matches { Self.writeHex(&$0, "hex", out) })
            case "frameEncode":
                let offer = SongTapSignedOffer(payload: Self.bytes(Self.string(c.input, "payload")), timestampMs: Self.long(c.input, "ts"),
                                        publicKey: Self.bytes(Self.string(c.input, "key")), signature: Self.bytes(Self.string(c.input, "sig")))
                let out = SongTapSigning.encodeFrame(offer)
                report.record(c, c.matches { Self.writeHex(&$0, "hex", out) })
            case "frameDecode":
                let offer = SongTapSigning.decodeFrame(Self.bytes(Self.string(c.input, "hex")))
                report.record(c, c.matches {
                    if let o = offer {
                        $0.bool("ok", true); Self.writeHex(&$0, "payload", o.payload); $0.long("ts", o.timestampMs)
                        Self.writeHex(&$0, "key", o.publicKey); Self.writeHex(&$0, "sig", o.signature)
                    } else {
                        $0.bool("ok", false)
                    }
                })
            case "senderKey":
                let key = SongTapSigning.senderKey(Self.bytes(Self.string(c.input, "key")))
                report.record(c, c.matches { $0.int("key", Int(key)) })
            default:
                report.record(c, false)
            }
        }
        report.verify(atLeast: 40)
    }

    // MARK: session.jsonl

    /// `SongTapSessionEvent.describe()` read back: `name(arg,arg)`, `-` for an empty video id.
    static func parseEvent(_ text: String) -> SongTapSessionEvent? {
        guard let open = text.firstIndex(of: "(") else {
            switch text {
            case "disarm": return .disarm
            case "offerRejected": return .offerRejected
            case "beamFinished": return .beamFinished
            case "decline": return .decline
            case "cancel": return .cancel
            case "dismiss": return .dismiss
            default: return nil
            }
        }
        let name = String(text[text.startIndex..<open])
        let inner = String(text[text.index(after: open)..<text.index(before: text.endIndex)])
        let a = inner.split(separator: ",", omittingEmptySubsequences: false).map(String.init)
        func n(_ i: Int) -> Int { Int(a[i]) ?? 0 }
        func l(_ i: Int) -> Int64 { Int64(a[i]) ?? 0 }
        func vid(_ i: Int) -> String { a[i] == "-" ? "" : a[i] }
        switch name {
        case "arm": return .arm(role: SongTapRole(rawValue: a[0]) ?? .send, askFirst: a[1] == "1")
        case "setRole": return .setRole(SongTapRole(rawValue: a[0]) ?? .send)
        case "peerFound": return .peerFound(n(0))
        case "peerLost": return .peerLost(n(0))
        case "peerNear": return .peerNear(n(0))
        case "peerFar": return .peerFar(n(0))
        case "peerRole": return .peerRole(peer: n(0), role: SongTapRole(rawValue: a[1]) ?? .send)
        case "peerDeclined": return .peerDeclined(n(0))
        case "tap": return .tapDetected(peer: n(0), videoId: vid(1))
        case "qrShown": return .qrShown(videoId: inner)
        case "offer": return .offerReceived(peer: n(0), videoId: a[1], senderKey: Int32(a[2]) ?? 0, nowMs: l(3))
        case "ack": return .ackReceived(nowMs: l(0), rttMs: l(1))
        case "go": return .goReceived(nowMs: l(0), rttMs: l(1))
        case "accept": return .accept(nowMs: l(0))
        case "saveResult": return .saveResult(SongTapSaveOutcome(rawValue: a[0]) ?? .failed, nowMs: l(1))
        case "undo": return .undo(nowMs: l(0))
        case "timeout": return .timeout(SongTapTimeoutTag(rawValue: a[0]) ?? .ack)
        default: return nil
        }
    }

    @Test func sessionTraces() throws {
        var report = Report(file: "session.jsonl")
        for c in try Self.cases("session.jsonl") {
            let events = Self.strings(c.input, "events").map { Self.parseEvent($0) }
            guard !events.contains(where: { $0 == nil }) else { report.record(c, false); continue }
            let steps = SongTapSession.run(start: .initial(askFirst: Self.bool(c.input, "askFirst")), events: events.compactMap { $0 })
            report.record(c, c.matches { w in
                w.beginArray("steps")
                for step in steps {
                    w.beginObject()
                    w.string("state", step.state.describe())
                    w.beginArray("effects")
                    for effect in step.effects { w.stringItem(effect.describe()) }
                    w.endArray()
                    w.endObject()
                }
                w.endArray()
            })
        }
        #expect(report.counts["trace"] ?? 0 >= 180)
        report.verify(atLeast: 180)
    }

    @Test func everyEventNameInTheTracesIsUnderstood() throws {
        var seen = Set<String>()
        for c in try Self.cases("session.jsonl") {
            for text in Self.strings(c.input, "events") {
                #expect(Self.parseEvent(text) != nil, "unparsed event \(text)")
                seen.insert(String(text.prefix { $0 != "(" }))
            }
        }
        #expect(seen.count >= 22, "the traces should use every event kind, saw \(seen.sorted())")
    }

    // MARK: detector.jsonl, impulse.jsonl, ratelimit.jsonl

    @Test func detectorTraces() throws {
        var report = Report(file: "detector.jsonl")
        for c in try Self.cases("detector.jsonl") {
            switch c.fn {
            case "detector":
                var state = SongTapDetectorState.initial
                var steps: [String] = []
                for sample in Self.strings(c.input, "samples") {
                    let p = sample.split(separator: ",").map { Int64($0) ?? 0 }
                    let step = SongTapDetector.step(state, SongTapRssiSample(tMs: p[0], rssi: Int(p[1])), impulseMs: p[2])
                    state = step.state
                    steps.append("\(step.fire.code),\(step.glowPermille),\(state.baselineQ),\(state.fastQ),\(state.near ? 1 : 0)")
                }
                report.record(c, c.matches { w in
                    w.beginArray("steps")
                    for s in steps { w.stringItem(s) }
                    w.endArray()
                })
            case "glow":
                let permille = SongTapDetector.glowPermille(Self.int(c.input, "fastQ"))
                report.record(c, c.matches { $0.int("permille", permille) })
            case "floorDiv":
                let q = SongTapDetector.floorDiv(Self.int(c.input, "a"), songTapRssiScale)
                report.record(c, c.matches { $0.int("q", q) })
            default:
                report.record(c, false)
            }
        }
        #expect(report.counts["detector"] ?? 0 >= 70)
        report.verify(atLeast: 80)
    }

    @Test func impulseTraces() throws {
        var report = Report(file: "impulse.jsonl")
        for c in try Self.cases("impulse.jsonl") {
            var state = SongTapImpulseState.initial
            var hits: [Int] = []
            for sample in Self.strings(c.input, "samples") {
                let p = sample.split(separator: ",").map { Int64($0) ?? 0 }
                let step = SongTapImpulse.step(state, SongTapAccelSample(tMs: p[0], xMg: Int(p[1]), yMg: Int(p[2]), zMg: Int(p[3])))
                state = step.state
                hits.append(step.impulse ? 1 : 0)
            }
            report.record(c, c.matches { w in
                w.beginArray("hits")
                for h in hits { w.intItem(h) }
                w.endArray()
            })
        }
        report.verify(atLeast: 45)
    }

    @Test func rateLimitScripts() throws {
        var report = Report(file: "ratelimit.jsonl")
        for c in try Self.cases("ratelimit.jsonl") {
            var limits = SongTapRateLimits()
            var verdicts: [String] = []
            for op in Self.strings(c.input, "ops") {
                let p = op.split(separator: ",", omittingEmptySubsequences: false).map(String.init)
                switch p[0] {
                case "admit":
                    verdicts.append(limits.admit(nowMs: Int64(p[1]) ?? 0, videoId: p[2], senderKey: Int32(p[3]) ?? 0).code)
                case "accepted":
                    limits = limits.accepted(nowMs: Int64(p[1]) ?? 0, videoId: p[2]); verdicts.append("-")
                case "attempted":
                    limits = limits.attempted(nowMs: Int64(p[1]) ?? 0); verdicts.append("-")
                default:
                    limits = limits.undone(nowMs: Int64(p[1]) ?? 0, senderKey: Int32(p[2]) ?? 0); verdicts.append("-")
                }
            }
            report.record(c, c.matches { w in
                w.beginArray("verdicts")
                for v in verdicts { w.stringItem(v) }
                w.endArray()
            })
        }
        report.verify(atLeast: 46)
    }

    // MARK: timeline.jsonl, haptics.jsonl, handshake.jsonl

    @Test func timelineFramesAndEasing() throws {
