                    $0.int("outCubic", SongTapTimeline.easeOutCubic(x)); $0.int("inCubic", SongTapTimeline.easeInCubic(x))
                    $0.int("smooth", SongTapTimeline.smooth(x)); $0.int("outBack", SongTapTimeline.easeOutBack(x))
                })
            case "frame":
                let frame = SongTapTimeline.frame(role: SongTapRole(rawValue: Self.string(c.input, "role")) ?? .send,
                                                  tMs: Self.long(c.input, "t"), reducedMotion: Self.bool(c.input, "reduced"))
